from flask import Flask, jsonify, request, abort, Response
from datetime import datetime, timezone
import copy
import json

app = Flask(__name__)

USERS = {
    "admin": {"role": "administrator", "projects": ["*"], "clearance": "high"},
    "pm": {"role": "project_manager", "projects": ["*"], "clearance": "medium"},
    "analyst": {"role": "analyst", "projects": ["alpha"], "clearance": "medium"},
    "guest": {"role": "guest", "projects": ["alpha"], "clearance": "low"},
}

STATE = {
    "projects": {
        "alpha": {
            "sensitivity": "normal",
            "approved_networks": ["corp"],
            "trusted_devices": ["trusted"],
            "items": {},
            "analyses": {},
            "exports": [],
            "audit": [],
        }
    }
}

COUNTERS = {"item": 0, "analysis": 0, "trace": 0}


def now():
    return datetime.now(timezone.utc).isoformat()


def current_user():
    name = request.headers.get("X-User", "guest")
    return name, USERS.get(name, USERS["guest"])


def project():
    pid = request.args.get("project") or request.json.get("project") if request.is_json else None
    if not pid:
        abort(400, "project required")
    if pid not in STATE["projects"]:
        abort(404, "unknown project")
    return pid, STATE["projects"][pid]


def can_access(user, pid):
    return "*" in user["projects"] or pid in user["projects"]


def log(project_obj, action, data):
    project_obj["audit"].append({"time": now(), **data, "action": action})


def next_id(prefix):
    COUNTERS[prefix] += 1
    return f"{prefix}-{COUNTERS[prefix]}"


@app.get("/health")
def health():
    return {"status": "ok"}


@app.post("/items")
def create_item():
    uname, user = current_user()
    payload = request.get_json(force=True)
    pid = payload.get("project")
    if not pid or pid not in STATE["projects"]:
        abort(400, "project required")
    if not can_access(user, pid):
        abort(403)
    item_id = next_id("item")
    item = {
        "id": item_id,
        "title": payload.get("title", ""),
        "description": payload.get("description", ""),
        "type": payload.get("type", "requirement"),
        "classifications": payload.get("classifications", []),
        "history": [],
        "traces": [],
        "derived_from": payload.get("derived_from"),
        "sensitive_notes": payload.get("sensitive_notes", ""),
        "version": 1,
        "active": True,
    }
    STATE["projects"][pid]["items"][item_id] = item
    log(STATE["projects"][pid], "create_item", {"user": uname, "item": item_id})
    return jsonify(item), 201


@app.post("/traces")
def create_trace():
    uname, user = current_user()
    payload = request.get_json(force=True)
    pid = payload.get("project")
    if pid not in STATE["projects"]:
        abort(400, "project required")
    if not can_access(user, pid):
        abort(403)
    proj = STATE["projects"][pid]
    src = proj["items"].get(payload.get("source_id"))
    dst = proj["items"].get(payload.get("target_id"))
    if not src or not dst:
        abort(404, "items required")
    if dst["type"] == "requirement" and payload.get("policy_claim") and not payload.get("policy_reference"):
        abort(400, "trace links required for policy claims")
    trace = {
        "id": next_id("trace"),
        "source_id": src["id"],
        "target_id": dst["id"],
        "policy_reference": payload.get("policy_reference"),
        "policy_excerpt": payload.get("policy_excerpt"),
        "rationale": payload.get("rationale", ""),
        "created_by": uname,
        "created_at": now(),
        "primary": bool(payload.get("primary")),
    }
    dst["traces"].append(trace)
    log(proj, "create_trace", {"user": uname, "trace": trace["id"]})
    return jsonify(trace), 201


@app.get("/compare")
def compare():
    pid = request.args.get("project")
    a = request.args.get("a")
    b = request.args.get("b")
    if pid not in STATE["projects"]:
        abort(404)
    proj = STATE["projects"][pid]
    an1 = proj["analyses"].get(a)
    an2 = proj["analyses"].get(b)
    if not an1 or not an2:
        abort(404)
    def by_id(items):
        return {i["id"]: i for i in items}
    return jsonify({
        "matches": sorted(set(by_id(an1["items"])) & set(by_id(an2["items"]))),
        "only_in_a": sorted(set(by_id(an1["items"])) - set(by_id(an2["items"]))),
        "only_in_b": sorted(set(by_id(an2["items"])) - set(by_id(an1["items"]))),
        "notes": "inline explanations: matches/differences based on item ids and trace links",
    })


@app.post("/analyses")
def create_analysis():
    uname, user = current_user()
    payload = request.get_json(force=True)
    pid = payload.get("project")
    if pid not in STATE["projects"]:
        abort(400)
    if not can_access(user, pid):
        abort(403)
    aid = next_id("analysis")
    proj = STATE["projects"][pid]
    proj["analyses"][aid] = {"id": aid, "name": payload.get("name", ""), "items": payload.get("items", [])}
    log(proj, "create_analysis", {"user": uname, "analysis": aid})
    return jsonify(proj["analyses"][aid]), 201


@app.get("/export")
def export_data():
    uname, user = current_user()
    pid = request.args.get("project")
    fmt = request.args.get("format", "json")
    if pid not in STATE["projects"]:
        abort(404)
    if not can_access(user, pid):
        abort(403)
    if user["role"] == "guest":
        abort(403)
    proj = STATE["projects"][pid]
    data = {"project": pid, "items": list(proj["items"].values()), "audit": proj["audit"]}
    if fmt == "json":
        return Response(json.dumps(data, indent=2), mimetype="application/json")
    if fmt == "csv":
        lines = ["id,title,type"]
        for item in proj["items"].values():
            lines.append(f"{item['id']},{item['title']},{item['type']}")
        return Response("\n".join(lines), mimetype="text/csv")
    abort(400)


@app.get("/items/<item_id>")
def get_item(item_id):
    pid = request.args.get("project")
    if pid not in STATE["projects"]:
        abort(404)
    item = STATE["projects"][pid]["items"].get(item_id)
    if not item:
        abort(404)
    uname, user = current_user()
    if user["role"] == "guest" and item.get("sensitive_notes"):
        item = copy.deepcopy(item)
        item.pop("sensitive_notes", None)
    return jsonify(item)


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
EOF

