    r4 = client.get('/export?project=alpha&format=json', headers={'X-User':'pm'})
    assert r4.status_code == 200
    data = json.loads(r4.data)
    assert data['project'] == 'alpha'


def test_guest_export_blocked():
    r = client.get('/export?project=alpha&format=json', headers={'X-User':'guest'})
    assert r.status_code == 403
